$destPath = Join-Path $DeployRoot "core/pipe_monitor.zig"

# Backup
if (Test-Path $destPath) {
    $backupPath = $destPath + ".phase4_backup"
    Copy-Item $destPath $backupPath -Force
    Write-Host "  [OK] Backup created"
}

# Decode and write
$content = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($FILE_3_B64))
# Remove BOM if present
if ($content.Length -ge 3 -and $content[0] -eq 0xFEFF) {
    $content = $content.Substring(1)
}
Set-Content -Path $destPath -Value $content -NoNewline -Encoding UTF8

# Verify line count
$lines = (Get-Content $destPath).Count
if ($lines -eq 170) {
    Write-Host "  [OK] Deployed: $lines lines (expected 170)"
    $SuccessCount++
} else {
    Write-Host "  [FAIL] Line count mismatch: $lines (expected 170)" -ForegroundColor Red
    $FailedFiles += "core/pipe_monitor.zig"
    # Rollback
    $backupPath = $destPath + ".phase4_backup"
    if (Test-Path $backupPath) { Copy-Item $backupPath $destPath -Force }
}

Write-Host "[4/$TotalFiles] Deploying core/windows_capture.zig..."
$destPath = Join-Path $DeployRoot "core/windows_capture.zig"

# Backup
if (Test-Path $destPath) {
    $backupPath = $destPath + ".phase4_backup"
    Copy-Item $destPath $backupPath -Force
    Write-Host "  [OK] Backup created"
}

# Decode and write
$content = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($FILE_4_B64))
# Remove BOM if present
if ($content.Length -ge 3 -and $content[0] -eq 0xFEFF) {
    $content = $content.Substring(1)
}
Set-Content -Path $destPath -Value $content -NoNewline -Encoding UTF8

# Verify line count
$lines = (Get-Content $destPath).Count
if ($lines -eq 114) {
    Write-Host "  [OK] Deployed: $lines lines (expected 114)"
    $SuccessCount++
} else {
    Write-Host "  [FAIL] Line count mismatch: $lines (expected 114)" -ForegroundColor Red
    $FailedFiles += "core/windows_capture.zig"
