Write-Host "[5/$TotalFiles] Deploying core/minifilter_reader.zig..."
$destPath = Join-Path $DeployRoot "core/minifilter_reader.zig"

# Backup
if (Test-Path $destPath) {
    $backupPath = $destPath + ".phase4_backup"
    Copy-Item $destPath $backupPath -Force
    Write-Host "  [OK] Backup created"
}

# Decode and write
$content = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($FILE_5_B64))
# Remove BOM if present
if ($content.Length -ge 3 -and $content[0] -eq 0xFEFF) {
    $content = $content.Substring(1)
}
Set-Content -Path $destPath -Value $content -NoNewline -Encoding UTF8

# Verify line count
$lines = (Get-Content $destPath).Count
if ($lines -eq 242) {
    Write-Host "  [OK] Deployed: $lines lines (expected 242)"
    $SuccessCount++
} else {
    Write-Host "  [FAIL] Line count mismatch: $lines (expected 242)" -ForegroundColor Red
    $FailedFiles += "core/minifilter_reader.zig"
    # Rollback
    $backupPath = $destPath + ".phase4_backup"
    if (Test-Path $backupPath) { Copy-Item $backupPath $destPath -Force }
}

Write-Host "[6/$TotalFiles] Deploying core/wfp_ioctl.zig..."
$destPath = Join-Path $DeployRoot "core/wfp_ioctl.zig"

# Backup
if (Test-Path $destPath) {
    $backupPath = $destPath + ".phase4_backup"
    Copy-Item $destPath $backupPath -Force
    Write-Host "  [OK] Backup created"
}

# Decode and write
$content = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($FILE_6_B64))
# Remove BOM if present
if ($content.Length -ge 3 -and $content[0] -eq 0xFEFF) {
    $content = $content.Substring(1)
}
Set-Content -Path $destPath -Value $content -NoNewline -Encoding UTF8

# Verify line count
$lines = (Get-Content $destPath).Count
if ($lines -eq 422) {
    Write-Host "  [OK] Deployed: $lines lines (expected 422)"
    $SuccessCount++
} else {
    Write-Host "  [FAIL] Line count mismatch: $lines (expected 422)" -ForegroundColor Red
    $FailedFiles += "core/wfp_ioctl.zig"
    # Rollback
    $backupPath = $destPath + ".phase4_backup"
    if (Test-Path $backupPath) { Copy-Item $backupPath $destPath -Force }
}

if ($FailedFiles.Count -gt 0) {
    Write-Host ""
    Write-Host "[FAIL] Deployment failed for: $($FailedFiles -join ", ")" -ForegroundColor Red
    Write-Host "[ROLLBACK] All files restored from backup"
    exit 1
}

Write-Host ""
Write-Host "[BUILD] Running zig build..."
$buildOutput = & zig build 2>&1
$buildExit = $LASTEXITCODE
if ($buildExit -eq 0) {
    Write-Host "[BUILD] SUCCESS - All Phase 4 fixes applied"
} else {
    Write-Host "[BUILD] FAILED - Rolling back all files" -ForegroundColor Red
    $buildOutput | ForEach-Object { Write-Host $_ }
    $bp_1 = Join-Path $DeployRoot "core/nids_analyze.zig" + ".phase4_backup"
    if (Test-Path $bp_1) { Copy-Item $bp_1 (Join-Path $DeployRoot "core/nids_analyze.zig") -Force }
    $bp_2 = Join-Path $DeployRoot "core/nids_capture.zig" + ".phase4_backup"
    if (Test-Path $bp_2) { Copy-Item $bp_2 (Join-Path $DeployRoot "core/nids_capture.zig") -Force }
    $bp_3 = Join-Path $DeployRoot "core/pipe_monitor.zig" + ".phase4_backup"
    if (Test-Path $bp_3) { Copy-Item $bp_3 (Join-Path $DeployRoot "core/pipe_monitor.zig") -Force }
    $bp_4 = Join-Path $DeployRoot "core/windows_capture.zig" + ".phase4_backup"
    if (Test-Path $bp_4) { Copy-Item $bp_4 (Join-Path $DeployRoot "core/windows_capture.zig") -Force }
    $bp_5 = Join-Path $DeployRoot "core/minifilter_reader.zig" + ".phase4_backup"
    if (Test-Path $bp_5) { Copy-Item $bp_5 (Join-Path $DeployRoot "core/minifilter_reader.zig") -Force }
    $bp_6 = Join-Path $DeployRoot "core/wfp_ioctl.zig" + ".phase4_backup"
    if (Test-Path $bp_6) { Copy-Item $bp_6 (Join-Path $DeployRoot "core/wfp_ioctl.zig") -Force }
    Write-Host "[ROLLBACK] Complete"
    exit 1
}

